package com.redcookies.archecraft.workbench;

import net.minecraft.core.Direction;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

// Generated by art/models/alchemy_workbench/build_model.py.
// Deliberately simple: decorative props are not separate outline/collision geometry.
final class AlchemyWorkbenchShapes {
    static VoxelShape[][] create() {
        VoxelShape[][] shapes = new VoxelShape[2][4];
        double[][][] boxes = {
            {
                {1, 0, 1, 16, 13, 15},
                {0.5, 13, 3, 13, 27, 11.5},
            },
            {
                {0, 0, 1, 15, 13, 15},
                {1.5, 13, 5.5, 12, 21.5, 13.5},
                {12, 13, 11.5, 16, 20.5, 15},
            },
        };
        for (int part=0; part<2; part++) {
            for (Direction facing : Direction.Plane.HORIZONTAL) {
                VoxelShape shape=Shapes.empty();
                for (double[] box : boxes[part]) {
                    double x0=box[0], z0=box[2], x1=box[3], z1=box[5];
                    for (int turn=0; turn < switch(facing) {case EAST -> 1; case SOUTH -> 2; case WEST -> 3; default -> 0;}; turn++) {
                        double nx0=16-z1, nz0=x0, nx1=16-z0, nz1=x1;
                        x0=nx0; z0=nz0; x1=nx1; z1=nz1;
                    }
                    shape=Shapes.or(shape,Block.box(x0,box[1],z0,x1,box[4],z1));
                }
                shapes[part][facing.get2DDataValue()]=shape.optimize();
            }
        }
        return shapes;
    }
}
